/** Events */
export const events = {
	castChanged: makeEvent<CastChanged, CastChanged>("cast-changed"),
	castFailed: makeEvent<CastFailed, CastFailed>("cast-failed"),
	dynamicRangeChanged: makeEvent<DynamicRangeChanged, DynamicRangeChanged>("dynamic-range-changed"),
	fullscreenChanged: makeEvent<FullscreenChanged, FullscreenChanged>("fullscreen-changed"),
	historyChanged: makeEvent<HistoryChanged, HistoryChanged>("history-changed"),
	menuAction: makeEvent<MenuAction, MenuAction>("menu-action"),
	playbackSkipped: makeEvent<PlaybackSkipped, PlaybackSkipped>("playback-skipped"),
	playerChanged: makeEvent<PlayerChanged, PlayerChanged>("player-changed"),
	playlistsChanged: makeEvent<PlaylistsChanged, PlaylistsChanged>("playlists-changed"),
	posterReady: makeEvent<PosterReady, PosterReady>("poster-ready"),
	queueChanged: makeEvent<QueueChanged, QueueChanged>("queue-changed"),
	scrolled: makeEvent<Scrolled, Scrolled>("scrolled"),
	settingsChanged: makeEvent<SettingsChanged, SettingsChanged>("settings-changed"),
	subtitleSyncChanged: makeEvent<SubtitleSyncChanged, SubtitleSyncChanged>("subtitle-sync-changed"),
};

/* Types */
export type AccentChoice = 
/**  One of the named accents in `design/color.ts`. */
{ kind: "preset"; id: string } | 
/**  Any OKLCH hue, 0–360. */
{ kind: "custom"; hue: number };

/**
 *  Where the AirPlay picker is to open from: the cast button, in the
 *  window's coordinates, from its top left.
 */
export type Anchor = {
	x: Real,
	y: Real,
	width: Real,
	height: Real,
};

export type AppError = 
/**  The settings or library database could not be read or written. */
{ kind: "database"; message: string } | 
/**  A file or directory operation failed. */
{ kind: "io"; message: string } | 
/**  Something the caller asked for does not exist. */
{ kind: "notFound"; message: string } | 
/**  The caller passed a value that cannot be used. */
{ kind: "invalid"; message: string } | 
/**  There is already something by that name. */
{ kind: "exists"; message: string } | 
/**  The playback engine reported a failure. */
{ kind: "engine"; message: string } | 
/**  The operation is not available on this system or for this media. */
{ kind: "unsupported"; message: string } | 
/**  A network request or cast device failed. */
{ kind: "network"; message: string } | 
/**  A bug in Lumen. The message is for the log, not for the user. */
{ kind: "internal"; message: string };

export type AppearanceSettings = {
	theme: ThemeMode,
	accent: AccentChoice,
};

/**  Somewhere sound can be sent. */
export type AudioDevice = {
	/**  What the engine knows it by. */
	id: string,
	/**  What macOS calls it. */
	name: string,
};

export type AudioSettings = {
	equaliser: Equaliser,
	/**  Gains saved by name. The ones Lumen comes with are not stored. */
	presets: EqualiserPreset[],
	/**
	 *  Where sound goes, as one of the player's `audio_devices`; `None`
	 *  follows the Mac's own output.
	 */
	device: string | null,
	channels: Channels,
	/**
	 *  Hand Dolby Digital and DTS to the output undecoded, for a receiver
	 *  to decode.
	 */
	passthrough: boolean,
	/**  Give a file that has no picture a drawing of its sound. */
	visualiser: boolean,
};

/**
 *  Casting changed: devices were found or lost, or a session started,
 *  moved on or ended. The whole state is sent each time.
 */
export type CastChanged = CastSnapshot;

/**  A device that can be cast to. */
export type CastDevice = {
	id: string,
	name: string,
	/**  What it is, as it says: "Chromecast", "Google TV Streamer". */
	model: string,
	protocol: CastProtocol,
	/**  It has a picture: a TV rather than a speaker. */
	video: boolean,
};

/**  Casting failed or ended on the device's account: what to tell the user. */
export type CastFailed = string;

export type CastPhase = 
/**  The AirPlay picker of macOS is open and nothing is chosen yet. */
"choosing" | 
/**  Reaching the device and starting its player. */
"connecting" | 
/**  The film is on the TV. */
"casting";

export type CastProtocol = "chromecast" | "airPlay";

/**  The session there is, if any. */
export type CastSession = {
	device: string,
	protocol: CastProtocol,
	phase: CastPhase,
	/**  How the open film reaches it, once that is decided. */
	delivery: Delivery | null,
};

export type CastSnapshot = {
	/**  Devices are being looked for. */
	searching: boolean,
	devices: CastDevice[],
	session: CastSession | null,
};

export type Channels = 
/**  What the output device says it has. */
"auto" | "stereo" | "surround51" | "surround71";

export type Chapter = {
	title: string | null,
	/**  Start, in seconds. */
	time: number,
};

export type Deinterlace = "off" | 
/**  Only frames the file marks as interlaced. */
"auto" | "on";

export type Delivery = "direct" | "remux" | "transcode";

export type DynamicRange = "sdr" | 
/**  HDR10 and other PQ content. */
"pq" | "hlg";

/**
 *  The picture began or stopped being shown in high dynamic range. While it
 *  is, its highlights can be several times brighter than the interface's
 *  white, so the chrome drawn over it outlines its marks (DESIGN.md §2).
 */
export type DynamicRangeChanged = boolean;

export type Equaliser = {
	enabled: boolean,
	/**  One gain for each of `BANDS`, in decibels. */
	gains: number[],
};

/**  A set of gains with a name, saved by the user. */
export type EqualiserPreset = {
	name: string,
	gains: number[],
};

export type FailureReason = 
/**  Nothing is at that path any more. */
{ kind: "missing" } | 
/**  It is there, but Lumen is not allowed to read it. */
{ kind: "noPermission" } | 
/**  It is a folder with nothing in it that could be played. */
{ kind: "folder" } | 
/**  It is not video or audio that Lumen can read. */
{ kind: "notMedia" } | 
/**  It was read, but no picture or sound in it could be played. */
{ kind: "nothingPlayable" } | 
/**  It is an address, and the network or the server would not give it. */
{ kind: "unreachable" } | 
/**  Anything else, in the engine's own words. */
{ kind: "other"; message: string };

/**
 *  What was chosen for one file. It is kept with the file's place in the
 *  history, and set again before the file is next loaded.
 * 
 *  Only choices are kept. A track the player picked by itself is not one:
 *  kept, it would stand in the way of a better pick later, when a
 *  preference has changed or another subtitle file has turned up.
 */
export type FileState = {
	/**  The audio track, by mpv's id; `None` leaves the choice to the player. */
	audio: number | null,
	/**  The subtitle track; `None` leaves the choice to the player. */
	subtitle: SubtitleChoice | null,
	secondSubtitle: number | null,
	/**  Subtitle files added by hand. */
	subtitleFiles: string[],
	/**  Seconds. */
	audioDelay: number,
	subtitleDelay: number,
	/**
	 *  How much faster than they are timed the subtitles run, when it is
	 *  not 1: a file timed for another frame rate, found by syncing.
	 */
	subtitleSpeed?: number | null,
	shape: Shape,
};

/**
 *  A window entered or left full screen, by any means: a command, the green
 *  button, or a Mission Control gesture.
 */
export type FullscreenChanged = boolean;

/**
 *  What has been played is not what it was: something was opened, forgotten
 *  or put back, or all of it was cleared. `history_recent` has it as it is
 *  now. The list is not sent with this, because each entry's poster is
 *  looked up, and made if need be, on the way out.
 * 
 *  Where a file was left is written far more often than this is said: only
 *  which things were played, and in what order, is worth saying.
 */
export type HistoryChanged = null;

/**  One thing that was played. */
export type HistoryEntry = {
	source: string,
	title: string,
	duration: number | null,
	/**  Seconds from the start, where playback last was. 0 once finished. */
	position: number,
	finished: boolean,
	/**  Unix seconds. */
	playedAt: number,
	/**
	 *  What was chosen for it the last time it was open: its tracks, its
	 *  delays, how its picture was shaped. `None` when nothing was.
	 */
	state: FileState | null,
	/**  The playlist it was last played in, if it was not played alone. */
	playlist: PlayedIn | null,
};

export type InspectorTab = "playlist" | "chapters" | "video" | "audio" | "subtitles";

/**
 *  How the interface was left. The interface owns these; the backend only
 *  keeps them.
 */
export type Interface = {
	/**  The time readout's second figure shows what is left, not the length. */
	timeRemaining: boolean,
	/**
	 *  The tab the panel beside the picture last showed. Whether it was
	 *  open is not kept: it always starts closed.
	 */
	inspectorTab: InspectorTab,
	/**  The actions last run from the command palette, newest first. */
	recentActions: string[],
};

/**
 *  An item of the menu bar that runs an action was chosen. The payload is
 *  the action's id.
 */
export type MenuAction = string;

export type MenuEntry = 
/**  An item that runs a registered action. */
{ kind: "action"; 
/**  The action's id. */
id: string; name: string; 
/**  Chord text as the interface writes it: "Shift+Cmd+p", "Space". */
shortcut: string | null; enabled: boolean; 
/**  For an action that switches something on and off: whether it is on. */
checked: boolean | null } | 
/**  A menu within the menu: one of several to choose from, or a list. */
{ kind: "submenu"; name: string; items: MenuEntry[] } | { kind: "separator" };

/**  One menu of the bar, as the interface describes it. */
export type MenuSection = {
	name: string,
	items: MenuEntry[],
};

/**
 *  The picture tuner. These stay until they are changed: they are about the
 *  room and the screen as much as about any one film.
 */
export type Picture = {
	/**  −100 to 100; 0 leaves the picture as it is. The same for the next four. */
	brightness: number,
	contrast: number,
	saturation: number,
	gamma: number,
	hue: number,
	/**  0 to 100; 0 is off. */
	sharpness: number,
	/**  0 to 100; 0 is off. */
	noiseReduction: number,
};

/**  A set of picture adjustments with a name, saved by the user. */
export type PicturePreset = {
	name: string,
	picture: Picture,
};

/**  An item of the queue would not play, and the next one is playing instead. */
export type PlaybackSkipped = {
	source: string,
	title: string,
	reason: FailureReason,
};

export type PlaybackStatus = 
/**  Nothing is open. */
"idle" | 
/**  A file or stream is being opened. */
"loading" | "playing" | "paused" | 
/**  Playing, but waiting for data. */
"buffering" | 
/**  The last file played to its end and is still open on its last frame. */
"ended";

/**
 *  A playlist as it stood when one of its items was played: enough to
 *  bring the whole of it back from Recently played.
 */
export type PlayedIn = {
	/**
	 *  Names this playlist across its items: the same for every item played
	 *  in one opening of it, and for a saved playlist every time it is opened.
	 */
	key: string,
	/**  The saved playlist's name, if it is one. */
	name: string | null,
	items: PlayedItem[],
};

/**  One item of a playlist that was played. */
export type PlayedItem = {
	source: string,
	title: string,
	duration: number | null,
};

/**  One change to the snapshot. */
export type PlayerChange = { type: "status"; status: PlaybackStatus } | 
/**  Something new is being opened, or the player went idle (`source: None`). */
{ type: "media"; source: string | null; title: string | null } | { type: "position"; seconds: number } | { type: "duration"; seconds: number | null } | { type: "volume"; percent: number } | { type: "muted"; muted: boolean } | { type: "speed"; rate: number } | { type: "video"; video: VideoInfo | null } | { type: "tracks"; tracks: Track[] } | { type: "chapters"; chapters: Chapter[] } | { type: "audioDelay"; seconds: number } | { type: "subtitleDelay"; seconds: number } | { type: "subtitleSpeed"; rate: number } | { type: "shape"; shape: Shape } | { type: "audioDevices"; devices: AudioDevice[] } | { type: "visualised"; visualised: boolean } | 
/**
 *  The file that has just loaded started where it was left last time
 *  rather than at its beginning.
 */
{ type: "resumed"; seconds: number } | 
/**  `source` could not be opened or stopped playing because of an error. */
{ type: "failed"; source: string; reason: FailureReason; 
/**
 *  What the Finder can show about it: the file if it is still there,
 *  else the nearest folder that is. Absent for an address.
 */
reveal: string | null };

/**
 *  The player's state changed. The interface folds each change into the
 *  snapshot it got from `player_snapshot`.
 */
export type PlayerChanged = PlayerChange;

/**  Everything the interface needs to draw the player, at one moment. */
export type PlayerSnapshot = {
	status: PlaybackStatus,
	/**  The path or URL that is open. */
	source: string | null,
	title: string | null,
	/**  Seconds from the start. */
	position: number,
	/**  Seconds; `None` for live streams and while loading. */
	duration: number | null,
	/**  0–200, where 100 is the file's own level. */
	volume: number,
	muted: boolean,
	speed: number,
	/**  `None` when the media has no picture. */
	video: VideoInfo | null,
	tracks: Track[],
	chapters: Chapter[],
	/**
	 *  How much later than the picture the sound is played, in seconds;
	 *  negative is earlier. Belongs to the file that is open.
	 */
	audioDelay: number,
	/**  How much later than they are timed the subtitles are shown, in seconds. */
	subtitleDelay: number,
	/**
	 *  How much faster than they are timed the subtitles run: 1 but for a
	 *  file timed for another frame rate.
	 */
	subtitleSpeed: number,
	/**  How the picture is turned, cut and stretched for this file. */
	shape: Shape,
	/**  Where sound can be sent, as macOS lists them. */
	audioDevices: AudioDevice[],
	/**  The picture is a drawing of the sound, made because the file has none. */
	visualised: boolean,
};

/**
 *  The saved playlists changed: one was saved, renamed, deleted or brought
 *  back. All of them are sent each time, so everything that lists them
 *  (the home screen, the menu bar, the palette) says the same.
 */
export type PlaylistsChanged = SavedPlaylist[];

/**  A poster that was not there when the history was read now is. */
export type PosterReady = {
	/**  What it is a poster for. */
	source: string,
	/**  Where the web view loads it from. */
	url: string,
};

/**
 *  The queue changed: what is in it, its order, which item is open, or how
 *  it repeats. The whole queue is sent each time.
 */
export type QueueChanged = QueueSnapshot;

/**  One thing in the queue. */
export type QueueItem = {
	/**  Unique within this run of the app; the interface refers to items by it. */
	id: number,
	source: string,
	title: string,
	/**  Seconds, once known. */
	duration: number | null,
	/**
	 *  Why it was stepped over the last time its turn came, if it was. It is
	 *  forgotten once the item does play.
	 */
	failed: FailureReason | null,
};

/**  The queue as the interface sees it. */
export type QueueSnapshot = {
	/**
	 *  In the order they are listed, which is the order they play in unless
	 *  shuffle is on.
	 */
	items: QueueItem[],
	/**  The id of the item that is open, if any. */
	current: number | null,
	/**  The saved playlist this queue was opened from or last saved as. */
	name: string | null,
	repeat: Repeat,
	shuffle: boolean,
	/**  Whether Next and Previous have somewhere to go. */
	hasNext: boolean,
	hasPrevious: boolean,
};

/**  A shape, as two whole numbers: 16:9, 235:100. */
export type Ratio = {
	width: number,
	height: number,
};

/**
 *  A number sent by the interface: seconds, a percentage, a rate.
 * 
 *  A bare `f64` argument would be typed `number | null` in TypeScript,
 *  because JSON cannot carry NaN or infinity. This is plain `number`; commands
 *  still reject values that are not finite.
 */
export type Real = number;

/**  A history entry as the home screen shows it. */
export type Recent = {
	/**
	 *  The file is where it was: false if it has been moved or deleted, or
	 *  its disk is not connected. Always true for an address.
	 */
	available: boolean,
	/**  Where the web view loads its poster from, once it has one. */
	poster: string | null,
	/**
	 *  Where opening it would start, in seconds, if not at its beginning:
	 *  the one rule for what resumes (`resume_point`), so the home screen
	 *  never promises a resume that will not happen.
	 */
	resumesAt: number | null,
} & HistoryEntry;

/**  What happens when the queue runs out, or an item ends. */
export type Repeat = 
/**  Stop after the last item. */
"off" | 
/**  Start again from the first. */
"all" | 
/**  Play the current item again when it ends. */
"one";

/**  A saved playlist, without its items. */
export type SavedPlaylist = {
	id: number,
	name: string,
	/**  How many items it holds. */
	count: number,
	/**  The length of the items whose length is known, in seconds. */
	duration: number,
	/**  Unix seconds. */
	updatedAt: number,
};

/**  Where a scroll gesture is in its course. */
export type ScrollPhase = 
/**  Fingers have started to move. */
"began" | 
/**  They are moving; also every notch of a wheel, which has no phases. */
"moved" | 
/**  They have lifted. */
"ended";

/**
 *  Fingers or a wheel scrolled over the main window. The glide macOS adds
 *  after the fingers lift is left out, which is why the page uses this and
 *  not its own wheel events for volume and seeking.
 */
export type Scrolled = {
	/**  Where the pointer is, in points from the window's top-left corner. */
	x: number,
	y: number,
	/**  How far the fingers moved, in points: right and up are positive. */
	right: number,
	up: number,
	/**  Fine movement (a trackpad), as opposed to the notches of a wheel. */
	precise: boolean,
	phase: ScrollPhase,
};

export type Session = {
	/**
	 *  0–100. A boost above 100 is not remembered: it is turned up for one
	 *  quiet film, and the next one should not start at twice the level.
	 */
	volume: number,
	muted: boolean,
	repeat: Repeat,
	shuffle: boolean,
	interface: Interface,
};

export type Settings = {
	appearance: AppearanceSettings,
	video: VideoSettings,
	audio: AudioSettings,
	subtitles: SubtitleSettings,
};

/**  Settings changed, in this window or another one. */
export type SettingsChanged = Settings;

/**
 *  How the picture is turned, cut and stretched. These belong to the file
 *  that is open: a phone video filmed sideways says nothing about the next
 *  film.
 */
export type Shape = {
	/**  The shape to show the picture in; `None` is the file's own. */
	aspect: Ratio | null,
	/**  Cut the picture, about its centre, to this shape; `None` shows all of it. */
	crop: Ratio | null,
	/**  1 fits the picture in the window; 2 shows it twice as large. */
	zoom: number,
	/**  Quarter turns clockwise, 0 to 3. */
	turns: number,
	/**  Top to bottom. */
	flipped: boolean,
	/**  Left to right. */
	mirrored: boolean,
	deinterlace: Deinterlace,
};

/**  Which subtitle track was chosen for a file. */
export type SubtitleChoice = 
/**  None: the user turned them off. */
"off" | 
/**  The track with this id. */
{ track: number };

/**  What looking for subtitles online needs. */
export type SubtitleSearch = {
	/**
	 *  The user's own key for the OpenSubtitles service; empty until they
	 *  give one.
	 */
	apiKey: string,
	/**  The languages to look for, most wanted first, as two-letter codes. */
	languages: string[],
};

export type SubtitleSettings = {
	style: SubtitleStyle,
	search: SubtitleSearch,
};

/**
 *  How subtitles look. For subtitles that are only text; ones that carry
 *  their own styling keep it unless `restyle` says otherwise.
 */
export type SubtitleStyle = {
	/**  A font family installed on this Mac; `None` is the system's own. */
	font: string | null,
	/**  1 is the usual size. */
	scale: number,
	bold: boolean,
	/**  `#RRGGBB`. */
	colour: string,
	outlineColour: string,
	/**  The outline's thickness, 0 to 4; 0 is none. */
	outline: number,
	/**  How opaque the box behind the words is, 0 to 1; 0 is no box. */
	background: number,
	/**  How far up from the bottom of the picture they stand, 0 to 100. */
	raise: number,
	/**  Use this style for subtitles that bring their own, too. */
	restyle: boolean,
};

/**
 *  Syncing the subtitles to the speech moved on: the model is downloading,
 *  samples are being listened to, or it is done.
 */
export type SubtitleSyncChanged = SyncStatus;

/**  How a sync is going, for the file and track it was started for. */
export type SyncStatus = 
/**
 *  Nothing is being synced. `installed`: the speech model is already
 *  here, so a sync starts listening at once.
 */
{ state: "idle"; installed: boolean } | 
/**  The speech model is being downloaded. */
{ state: "installing"; source: string; track: number; 
/**  0–1. */
progress: number; 
/**  The model's size, in bytes. */
size: number } | 
/**  Samples of the film are being listened to. */
{ state: "listening"; source: string; track: number; done: number; total: number } | 
/**  A timing was found and is in effect. */
{ state: "synced"; source: string; track: number; speed: number; delay: number; 
/**
 *  How it was found: from words, or only from when people speak
 *  (the subtitles are in another language than the sound).
 */
byWords: boolean; 
/**  Samples that agreed, of those in which anything was heard. */
agreeing: number; heard: number; 
/**  The timing before, which Undo puts back. */
speedBefore: number; delayBefore: number } | 
/**  No timing could be found, or something went wrong. */
{ state: "failed"; source: string; track: number; message: string };

export type ThemeMode = 
/**  Follow the macOS appearance. */
"system" | 
/**  Lumen is dark-first. */
"dark" | "light";

/**  One file of a fetched torrent. */
export type TorrentFile = {
	index: number,
	/**  The file's name, without the folders it is in. */
	name: string,
	size: number,
	/**  Lumen plays it: a video or an audio file. */
	playable: boolean,
};

/**  How a torrent that was asked for is getting on. */
export type TorrentProgress = 
/**  Being fetched. `progress` is 0–100; `speed` in bytes a second. */
{ phase: "working"; name: string; state: string; progress: number; speed: number; seeders: number } | 
/**  Fetched: its files can be played. */
{ phase: "ready"; name: string; files: TorrentFile[] } | 
/**  It will not come. `message` is for the user. */
{ phase: "failed"; message: string };

/**  One torrent found by a search. */
export type TorrentResult = {
	name: string,
	/**  Lower-case hex, 40 characters. */
	hash: string,
	magnet: string,
	/**  As the index gives it: "1.4 GB". */
	size: string,
	seeders: number,
	leechers: number,
	/**  The day it was added, as `YYYY-MM-DD`, if known. */
	uploaded: string | null,
	category: string | null,
	/**  The uploader is one the index vouches for. */
	trusted: boolean,
	/**
	 *  TorBox already has it, so it plays in seconds. `None` if that could
	 *  not be found out.
	 */
	ready: boolean | null,
};

export type Track = {
	/**  mpv's id, unique within its kind. */
	id: number,
	kind: TrackKind,
	title: string | null,
	/**  Language tag from the file, e.g. "eng". */
	language: string | null,
	/**  Short codec name, e.g. "hevc", "ac3", "subrip". */
	codec: string | null,
	selected: boolean,
	default: boolean,
	forced: boolean,
	/**  Loaded from a separate file rather than the container. */
	external: boolean,
	/**  That file, for a track that is external. */
	file: string | null,
	/**  Subtitles only: selected as the second track, shown above the first. */
	secondary: boolean,
	/**  Audio only. */
	channels: number | null,
};

export type TrackKind = "video" | "audio" | "subtitle";

export type VideoInfo = {
	/**  Display size in pixels, after aspect correction and rotation. */
	width: number,
	height: number,
	fps: number | null,
	codec: string | null,
	dynamicRange: DynamicRange,
	/**  The hardware decoder in use, or `None` for software decoding. */
	hardwareDecoder: string | null,
};

/**  The picture tuner, and the adjustments saved from it by name. */
export type VideoSettings = {
	picture: Picture,
	presets: PicturePreset[],
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

type EventEmitTo<T> = [T] extends [null] ? (target: __TAURI_EVENT.EventTarget | string) => Promise<void> : (target: __TAURI_EVENT.EventTarget | string, payload: T) => Promise<void>;

function makeEvent<TListen, TEmit = TListen>(name: string, serialize?: (payload: TEmit) => unknown, deserialize?: (payload: any) => TListen) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<TListen>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: TEmit) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => __TAURI_EVENT.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => target.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    });

    return Object.assign(fn, base);
}

